/**
 * Metadata lookup jobs for import projects: the automatic trigger after the confirmation that completes the file set (or a re-rank
 * of the stored candidates when it completes nothing new), stale marking when a bound file is removed, admission of submitted and
 * retried runs, and the persisted worker that advances one run one MusicBrainz request per stored step and applies a completed
 * run's preselection (lookupValueApplication.ts) in the step that completes it. Starting a run, every state change and a re-rank
 * write the import document's `lookupGate` in the same transaction, and an application writes the document itself; neither ever
 * changes its `revision`. A trigger that starts nothing, stale marking of a finished run and progress steps do not write it.
 * Owner rules: the confirmed Administrator Metadata Lookup rules (they land with the summary).
 */
import { randomUUID } from 'node:crypto';
import { ObjectId, type ClientSession } from 'mongodb';
import { metadataLookupConfiguration, type MetadataLookupConfiguration } from '../../config/metadataLookup';
import { getDatabaseClient, getDb } from '../../infrastructure/database';
import { pinnedHttpsTransport } from '../adminPinnedHttps';
import { startAdminWorker, type AdminWorkTracker } from '../adminWorkerLifecycle';
import { AdminImportError, importEnabled, objectId, uuid } from '../import/adminImportContract';
import { importDraftWritable } from '../import/adminImportDraftCompat';
import { importSourcesLocked } from '../import/adminImportMediaTypes';
import {
    importCollection, importPurposeFilter, isDraftV2Document, isImportProject, touchImportAdmin, withImportAdmin, type AdminImportDocument
} from '../import/adminImportService';
import { storedDraftV2 } from '../import/adminImportValueState';
import {
    ADMIN_IMPORT_LOOKUP_COLLECTION, METADATA_LOOKUP_JOB_LIMITS as JOB, MetadataLookupInputError, MetadataLookupSourceError,
    type LookupGateMode, type MusicBrainzRelease, type MusicBrainzReleaseSummary
} from './lookupContract';
import { lookupTermProblem } from './lookupIdentifiers';
import type { PlannedLookupQuery } from './lookupQueryPlanner';
import { createMongoLookupRateGate } from './lookupRateGate';
import { createLookupResponseCache } from './lookupResponseCache';
import { createMusicBrainzClient, type MusicBrainzClient } from './musicBrainzClient';
import { applyPreselectedLookup, rerankStoredLookup } from './lookupValueApplication';
import {
    automaticLookupOperationId, importLookupFileSet, isBlockingLookupState, lookupGateFor, lookupRetryAt, lookupStaleSlots,
    mergeLookupCandidates, planImportLookup, rankLookupWithinBudget, recordLookupDetails, startLookupRun,
    type MetadataLookupInput, type MetadataLookupIssue, type MetadataLookupRecord, type MetadataLookupState, type MetadataLookupSubmission
} from './metadataLookupRecord';

export const adminImportLookupCollection = () => getDb()!.collection<MetadataLookupRecord>(ADMIN_IMPORT_LOOKUP_COLLECTION);
const lookups = adminImportLookupCollection;
/** The options withImportAdmin uses, so worker steps read and write one snapshot. */
const transactionOptions = { readConcern: { level: 'snapshot' as const }, writeConcern: { w: 'majority' as const }, maxCommitTimeMS: 10_000 };
const lookupConfiguration = (configuration?: () => MetadataLookupConfiguration) => (configuration ?? (() => metadataLookupConfiguration()))();

/** Lookup applies only to a writable Draft v2 import project whose sources no publication locks and that has not completed. */
export function metadataLookupAccepted(doc: AdminImportDocument): boolean {
    if (!isImportProject(doc) || !isDraftV2Document(doc) || !importDraftWritable(doc) || doc.catalogApplied
        || importSourcesLocked(doc.media) || doc.media?.publication?.state === 'complete') return false;
    // A malformed stored draft is left for a reload, as automation leaves it.
    try { storedDraftV2(doc); return true; } catch { return false; }
}

/** Fence write: in memory for a caller that later replaces `doc`, and persisted for one that does not; never touches `revision`. */
async function writeLookupGate(doc: AdminImportDocument, record: Pick<MetadataLookupRecord, 'run' | 'state'>, session: ClientSession) {
    doc.lookupGate = lookupGateFor(record, doc.lookupGate);
    await importCollection().updateOne({ _id: doc._id }, { $set: { lookupGate: doc.lookupGate } }, { session });
}

/**
 * Marks bound slots whose file was replaced or removed: a blocking run is superseded (gate written first), a finished run records
 * them in `staleSlotIds` without changing any value. Returns the stored record, or the unchanged one.
 */
async function reconcileLookupFiles(doc: AdminImportDocument, record: MetadataLookupRecord | null, files: ReturnType<typeof importLookupFileSet>['files'],
    session: ClientSession, now: Date): Promise<MetadataLookupRecord | null> {
    if (!record || !Array.isArray(record.files)) return record;
    const stale = lookupStaleSlots(record.files, files);
    const staleSlotIds = [...new Set([...(Array.isArray(record.staleSlotIds) ? record.staleSlotIds : []), ...stale])];
    if (!stale.length || (!isBlockingLookupState(record.state) && staleSlotIds.length === record.staleSlotIds?.length)) return record;
    const next: MetadataLookupRecord = isBlockingLookupState(record.state)
        ? { ...record, state: 'superseded', issue: 'fileSetChanged', staleSlotIds, retryAt: null, leaseOwner: null, leaseUntil: null, updatedAt: now, completedAt: now }
        : { ...record, staleSlotIds, updatedAt: now };
    if (next.state !== record.state) await writeLookupGate(doc, next, session);
    await lookups().replaceOne({ _id: record._id }, next, { session });
    return next;
}

export type MetadataLookupTriggerOutcome = { queued: boolean; run: number | null;
    reason: 'queued' | 'noQuery' | 'unavailable' | 'closed' | 'incomplete' | 'current' | 'limit' | 'failed' };
/**
 * Re-ranks a completed run's stored candidates against newly known evidence without any request, in the trigger's transaction
 * (whose administrator, rechecked there, applies a new preselection): the gate first (fencing the re-rank), then the document
 * when a new preselection wrote values, then the record.
 */
async function rerankLookup(doc: AdminImportDocument, record: MetadataLookupRecord | null, actor: string, session: ClientSession, now: Date) {
    const reranked = record && rerankStoredLookup(doc, record, now, actor);
    if (!reranked) return;
    await writeLookupGate(doc, reranked.record, session);
    if (reranked.changed) {
        const written = await importCollection().replaceOne({ _id: doc._id, revision: doc.revision }, doc, { session });
        if (written.matchedCount !== 1) throw new Error('METADATA_LOOKUP_RERANK_CONFLICT');
    }
    await lookups().replaceOne({ _id: doc._id, run: reranked.record.run }, reranked.record, { session });
}

/**
 * Automatic trigger after an upload or reconcile confirmed a file, as `actor` (who must still hold the role). It queues a run once
 * every selected audio file is confirmed and the file set differs from the last run's, within the per-project automatic limit. A
 * replay, a second reconcile or a racing confirmation finds the same file set and queues nothing. A confirmation that leaves the
 * file set incomplete, or reaches the limit, re-ranks a completed run's stored candidates instead when the evidence changed. Never
 * throws; the confirmation keeps its own result.
 */
export async function requestAutomaticMetadataLookup(actor: string, id: string, grant: 'upload' | 'reopen',
    options: { now?: Date; configuration?: () => MetadataLookupConfiguration } = {}): Promise<MetadataLookupTriggerOutcome> {
    const outcome = (reason: MetadataLookupTriggerOutcome['reason'], run: number | null = null): MetadataLookupTriggerOutcome => ({ queued: reason === 'queued', run, reason });
    if (!objectId(id) || !lookupConfiguration(options.configuration).available) return outcome('unavailable');
    try {
        return await withImportAdmin(actor, async session => {
            const now = options.now ?? new Date();
            const doc = await importCollection().findOne({ _id: new ObjectId(id), ...importPurposeFilter }, { session });
            if (!doc || !metadataLookupAccepted(doc)) return outcome('closed');
            const fileSet = importLookupFileSet(doc);
            const record = await reconcileLookupFiles(doc, await lookups().findOne({ _id: doc._id }, { session }), fileSet.files, session, now);
            if (!fileSet.complete) { await rerankLookup(doc, record, actor, session, now); return outcome('incomplete'); }
            if (record?.fileSetDigest === fileSet.digest) return outcome('current');
            if ((record?.automaticRuns ?? 0) >= JOB.automaticRuns) { await rerankLookup(doc, record, actor, session, now); return outcome('limit'); }
            // A rerun after a submitted run repeats the submitted text; otherwise it plans from the current tags and folder.
            const submitted = record?.input?.trigger === 'submitted' && record.input.submitted ? record.input.submitted : undefined;
            const planned = planImportLookup(doc, { folderAvailable: record?.folderUsed !== true, submitted });
            const run = startLookupRun(record, {
                importId: doc._id, actorId: actor, grantSource: grant, automatic: true, now, fileSet,
                operationId: automaticLookupOperationId(id, (record?.run ?? 0) + 1, fileSet.digest),
                input: planned.input, queries: planned.plan.queries
            });
            // The gate goes first: racing first runs then conflict on the import document (retried), never on a duplicate key.
            await writeLookupGate(doc, run, session);
            await lookups().replaceOne({ _id: doc._id }, run, { upsert: true, session });
            return outcome(run.state === 'queued' ? 'queued' : 'noQuery', run.run);
        });
    } catch { return outcome('failed'); }
}

/** Inside a transaction that will replace `doc`: stale marking and supersession after a file was removed (cleanup admission). */
export async function noteMetadataLookupFiles(doc: AdminImportDocument, session: ClientSession, now = new Date()): Promise<void> {
    if (!isImportProject(doc) || !isDraftV2Document(doc)) return;
    const record = await lookups().findOne({ _id: doc._id }, { session });
    await reconcileLookupFiles(doc, record, importLookupFileSet(doc).files, session, now);
}

export type MetadataLookupRequest =
    | { kind: 'submit'; actorId: string; operationId: string; submitted: MetadataLookupSubmission }
    | { kind: 'retry'; actorId: string; operationId: string };
const refuse = (status: number, code: string) => new AdminImportError(status, code);
/** A stored run input this release can repeat; another release's shape is not retried. */
const retryableInput = (input: unknown): input is MetadataLookupInput => {
    const value = input as Partial<MetadataLookupInput> | null;
    if (!value || typeof value !== 'object') return false;
    if (value.trigger === 'tags' || value.trigger === 'folder') return true;
    const submitted = value.submitted;
    return value.trigger === 'submitted' && !!submitted && typeof submitted === 'object' && (submitted.kind === 'album' || submitted.kind === 'song') && typeof submitted.text === 'string';
};
/**
 * Admits a submitted or manually retried run inside the caller's administrator transaction, replacing the previous run; the
 * granting administrator is rechecked in that transaction. A submission binds the current file set (complete or not) and
 * refuses a link, an empty, over-long or invisible-character name; a retry repeats the last run's queries and is refused while
 * a run is queued or running (one waiting for an automatic retry is replaced). The caller records its own receipt.
 */
export async function queueMetadataLookup(doc: AdminImportDocument, request: MetadataLookupRequest, session: ClientSession,
    options: { now?: Date; configuration?: () => MetadataLookupConfiguration } = {}): Promise<MetadataLookupRecord> {
    const now = options.now ?? new Date();
    if (!lookupConfiguration(options.configuration).available) throw refuse(503, 'ADMIN_IMPORT_LOOKUP_UNAVAILABLE');
    if (!request || (request.kind !== 'submit' && request.kind !== 'retry') || !objectId(request.actorId) || !uuid(request.operationId)) throw refuse(400, 'ADMIN_IMPORT_INVALID_INPUT');
    await touchImportAdmin(request.actorId, session);
    if (!metadataLookupAccepted(doc)) throw refuse(409, 'ADMIN_IMPORT_LOOKUP_REFUSED');
    const record = await lookups().findOne({ _id: doc._id }, { session }), fileSet = importLookupFileSet(doc);
    const base = { importId: doc._id, actorId: request.actorId, operationId: request.operationId, automatic: false, now, fileSet };
    let run: MetadataLookupRecord;
    if (request.kind === 'submit') {
        const submitted = request.submitted;
        if (!submitted || (submitted.kind !== 'album' && submitted.kind !== 'song') || lookupTermProblem(submitted.text) !== null) throw refuse(400, 'ADMIN_IMPORT_LOOKUP_INVALID_NAME');
        const planned = planImportLookup(doc, { folderAvailable: false, submitted });
        if (planned.plan.rejected || !planned.plan.queries.length) throw refuse(400, 'ADMIN_IMPORT_LOOKUP_INVALID_NAME');
        run = startLookupRun(record, { ...base, grantSource: 'submit', input: planned.input, queries: planned.plan.queries });
    } else {
        if (!record || !Array.isArray(record.queries) || !record.queries.length || !retryableInput(record.input)) throw refuse(409, 'ADMIN_IMPORT_LOOKUP_NOTHING_TO_RETRY');
        // The run filter discards a replaced run's late steps, so only a run that may be sending refuses a retry.
        if (record.state === 'queued' || record.state === 'running') throw refuse(409, 'ADMIN_IMPORT_LOOKUP_ACTIVE');
        run = startLookupRun(record, { ...base, grantSource: 'retry', input: record.input, queries: record.queries });
    }
    await writeLookupGate(doc, run, session);
    await lookups().replaceOne({ _id: doc._id }, run, { upsert: true, session });
    return run;
}

type LookupAction = { kind: 'search'; index: number; query: PlannedLookupQuery } | { kind: 'details'; releaseId: string };
type FoundRelease = { releaseId: string; summary?: MusicBrainzReleaseSummary; release?: MusicBrainzRelease };
/** What one request answered, mapped so that the step that stores it never needs the source's errors. */
type LookupStepResult =
    | { kind: 'found'; action: LookupAction & { kind: 'search' }; found: FoundRelease[] }
    | { kind: 'details'; action: LookupAction & { kind: 'details' }; release: MusicBrainzRelease | null }
    | { kind: 'refused'; action: LookupAction }
    | { kind: 'failed'; failure: 'busy' | 'unavailable'; retryAfterMs: number | null }
    | { kind: 'notConfigured' }
    | { kind: 'shutdown' };
type LookupStep = { action: LookupAction | null; mode: LookupGateMode };
const idle: LookupStep = { action: null, mode: 'wait' };

/** Performs one request outside any transaction, bounded by the step deadline; never throws. */
async function performLookupAction(client: MusicBrainzClient, action: LookupAction, mode: LookupGateMode, signal?: AbortSignal): Promise<LookupStepResult> {
    const deadline = AbortSignal.timeout(JOB.stepDeadlineMs);
    const options = { mode, signal: signal ? AbortSignal.any([signal, deadline]) : deadline };
    try {
        if (action.kind === 'details') return { kind: 'details', action, release: await client.lookupRelease(action.releaseId, options) };
        const found = (items: FoundRelease[]): LookupStepResult => ({ kind: 'found', action, found: items });
        const { query } = action;
        switch (query.kind) {
            // Keyed by the release MusicBrainz returned: a merged release answers an old ID with its current one.
            case 'musicBrainzRelease': { const release = await client.lookupRelease(query.releaseId, options); return found(release ? [{ releaseId: release.releaseId, release }] : []); }
            case 'musicBrainzReleaseSearch': return found((await client.searchReleases(query.query, options)).releases.map(summary => ({ releaseId: summary.releaseId, summary })));
            case 'musicBrainzRecordingSearch': return found((await client.searchRecordings(query.query, options)).recordings.flatMap(hit => hit.releases.map(release => ({ releaseId: release.releaseId }))));
            case 'musicBrainzIsrc': return found(((await client.lookupIsrc(query.isrc, options))?.recordings ?? []).flatMap(recording => recording.releaseIds.map(releaseId => ({ releaseId }))));
            // A query kind a later release stored is skipped rather than sent.
            default: return { kind: 'refused', action };
        }
    } catch (error) {
        if (error instanceof MetadataLookupInputError) return { kind: 'refused', action };
        if (signal?.aborted) return { kind: 'shutdown' };
        if (error instanceof MetadataLookupSourceError) {
            if (error.failure === 'notConfigured') return { kind: 'notConfigured' };
            // `cancelled` here is the step deadline: the source did not answer in time.
            return { kind: 'failed', failure: error.failure === 'busy' ? 'busy' : 'unavailable', retryAfterMs: error.retryAfterMs };
        }
        return { kind: 'failed', failure: 'unavailable', retryAfterMs: null };
    }
}

/** Ends a run: the lease and retry are cleared and nothing else from the step that ended it is stored. */
const endRun = (record: MetadataLookupRecord, state: MetadataLookupState, issue: MetadataLookupIssue | null, now: Date, extra: Partial<MetadataLookupRecord> = {}): MetadataLookupRecord =>
    ({ ...record, ...extra, state, issue, retryAt: null, leaseOwner: null, leaseUntil: null, updatedAt: now, completedAt: now });

/**
 * Stores one request's result and decides the next request (pure): the planned queries in order until 25 candidates are known,
 * then each pending candidate's details, then ranking. A source failure schedules an automatic retry; once retries run out, a
 * search ends unavailable (never "no release") and missing details leave their candidates incomplete in a completed run.
 */
function proceedLookup(record: MetadataLookupRecord, doc: AdminImportDocument, result: LookupStepResult | null, now: Date): { next: MetadataLookupRecord; step: LookupStep } {
    let next: MetadataLookupRecord = { ...record, updatedAt: now }, issue: MetadataLookupIssue | null = null;
    if (result?.kind === 'notConfigured') return { next: endRun(record, 'unavailable', 'notConfigured', now), step: idle };
    if (result?.kind === 'failed') {
        const failures = (Number.isSafeInteger(record.attempts?.musicbrainz) ? record.attempts.musicbrainz : 0) + 1;
        const retryAt = lookupRetryAt(failures, now, result.retryAfterMs), failed = result.failure === 'busy' ? 'sourceBusy' : 'sourceUnavailable';
        next = { ...next, attempts: { ...record.attempts, musicbrainz: failures } };
        // A retry its grant would not reach counts as exhausted, so a run never stays blocking past its grant.
        if (retryAt && retryAt < record.grantExpiresAt) return { next: { ...next, state: 'retrying', issue: failed, retryAt, leaseOwner: null, leaseUntil: null }, step: idle };
        if (next.phase === 'search') return { next: endRun(next, 'unavailable', failed, now), step: idle };
        next.candidates = next.candidates.map(candidate => candidate.details === 'pending' ? { ...candidate, details: 'failed' } : candidate);
        issue = 'sourceUnavailable';
    } else if (result?.kind === 'found' && next.phase === 'search' && next.queryIndex === result.action.index) {
        next = { ...next, candidates: mergeLookupCandidates(next.candidates, result.found, result.action.query.basis), queryIndex: next.queryIndex + 1 };
    } else if (result?.kind === 'details') {
        next.candidates = recordLookupDetails(next.candidates, result.action.releaseId, result.release);
    } else if (result?.kind === 'refused') {
        if (result.action.kind === 'search' && next.phase === 'search' && next.queryIndex === result.action.index) next.queryIndex++;
        else if (result.action.kind === 'details') next.candidates = recordLookupDetails(next.candidates, result.action.releaseId, 'failed');
    }
    // A submitted run uses busy mode until its first failed attempt; automatic runs (also reruns of submitted text) and manual retries wait.
    const mode: LookupGateMode = next.grantSource === 'submit' && !next.attempts?.musicbrainz ? 'busy' : 'wait';
    const running = (action: LookupAction, phase: MetadataLookupRecord['phase']) => ({
        next: { ...next, state: 'running' as const, issue: null, phase, retryAt: null, leaseUntil: new Date(now.getTime() + JOB.leaseMs),
            // Stored before the request is sent, so the folder allowance is spent only once a folder name may have left.
            folderUsed: next.folderUsed === true || (action.kind === 'search' && action.query?.basis === 'folder') }, step: { action, mode }
    });
    if (next.phase === 'search' && next.queryIndex < next.queries.length && next.candidates.length < JOB.candidates) {
        return running({ kind: 'search', index: next.queryIndex, query: next.queries[next.queryIndex] }, 'search');
    }
    const pending = next.candidates.find(candidate => candidate.details === 'pending');
    if (pending) return running({ kind: 'details', releaseId: pending.releaseId }, 'details');
    // The single place where a run is ranked as it completes; advanceLookup applies its preselection in the same step.
    const ranked = rankLookupWithinBudget(next.candidates, doc, now);
    return { next: endRun(next, 'complete', issue, now, { phase: 'done', outcome: next.candidates.length ? 'candidates' : 'noRelease',
        candidates: ranked.candidates, ranking: ranked.ranking }), step: idle };
}

/**
 * One stored step in one transaction: the lease, the grant, the actor's current role, the project and the bound file set are
 * checked before anything is stored. A lost lease writes nothing; a stop keeps earlier candidates but never this step's result.
 * The step that completes a run applies its preselection: values, gate and record commit together or not at all.
 */
async function advanceLookup(id: ObjectId, run: number, worker: string, now: Date, result: LookupStepResult | null,
    configuration: () => MetadataLookupConfiguration): Promise<LookupStep> {
    const session = getDatabaseClient().startSession();
    let step = idle;
    try {
        await session.withTransaction(async () => {
            step = idle;
            const record = await lookups().findOne({ _id: id, run, leaseOwner: worker }, { session });
            if (!record) return;
            const doc = await importCollection().findOne({ _id: id, ...importPurposeFilter }, { session });
            let next: MetadataLookupRecord, permitted = true, applied = false;
            if (record.grantExpiresAt instanceof Date && record.grantExpiresAt > now) {
                // Role loss and a deleted account both fail this fence; the transaction itself stays usable.
                try { await touchImportAdmin(record.actorId, session); } catch (error) { if (!(error instanceof AdminImportError)) throw error; permitted = false; }
            }
            // Stale files are compared only after the grant check, so a run whose stored progress cannot be read ends with its grant.
            const stale = () => lookupStaleSlots(record.files, importLookupFileSet(doc!).files);
            let staleSlots: string[] = [];
            if (!isBlockingLookupState(record.state)) next = { ...record, leaseOwner: null, leaseUntil: null };
            else if (!(record.grantExpiresAt instanceof Date) || record.grantExpiresAt <= now) next = endRun(record, 'stopped', 'grantExpired', now);
            else if (!permitted) next = endRun(record, 'stopped', 'permissionLost', now);
            else if (!doc || !metadataLookupAccepted(doc)) next = endRun(record, 'superseded', 'projectClosed', now);
            else if ((staleSlots = stale()).length) next = endRun(record, 'superseded', 'fileSetChanged', now, { staleSlotIds: [...new Set([...(record.staleSlotIds ?? []), ...staleSlots])] });
            else if (!configuration().available) next = endRun(record, 'unavailable', 'notConfigured', now);
            else {
                ({ next, step } = proceedLookup(record, doc, result, now));
                if (next.state === 'complete' && next.phase === 'done') ({ record: next, changed: applied } = applyPreselectedLookup(doc, next, now));
            }
            if (next.state !== record.state && doc) await writeLookupGate(doc, next, session);
            if (applied && doc) {
                const values = await importCollection().replaceOne({ _id: doc._id, revision: doc.revision }, doc, { session });
                if (values.matchedCount !== 1) throw new Error('METADATA_LOOKUP_STEP_CONFLICT');
            }
            const written = await lookups().replaceOne({ _id: id, run, leaseOwner: worker }, next, { session });
            if (written.matchedCount !== 1) throw new Error('METADATA_LOOKUP_STEP_CONFLICT');
        }, transactionOptions);
    } finally { await session.endSession(); }
    return step;
}

/** Releases this worker's lease without changing progress, so the next tick resumes at the stored step. */
const releaseLookupLease = (id: ObjectId, run: number, worker: string) =>
    lookups().updateOne({ _id: id, run, leaseOwner: worker }, { $set: { leaseOwner: null, leaseUntil: null } });

export type MetadataLookupWorkerDependencies = { musicBrainz?: MusicBrainzClient; configuration?: () => MetadataLookupConfiguration; now?: () => Date };
/** Production client: the deployment-wide MongoDB gate, the pinned fetcher and one process-local response cache. */
const defaultMusicBrainzClient = (configuration?: () => MetadataLookupConfiguration) => createMusicBrainzClient({
    gate: createMongoLookupRateGate(getDb()!), transport: pinnedHttpsTransport, cache: createLookupResponseCache(), ...(configuration ? { configuration } : {})
});
/** More steps than any run needs (six queries, 25 details, retries end the tick); a safety bound against a step that stores nothing. */
const maximumStepsPerTick = 64;

/** Claims one due run and advances it, one MusicBrainz request per stored step, until it ends, waits for a retry, or loses its lease. */
export async function runMetadataLookupOnce(dependencies: MetadataLookupWorkerDependencies = {}, signal?: AbortSignal): Promise<boolean> {
    if (signal?.aborted || !importEnabled()) return false;
    const clock = dependencies.now ?? (() => new Date());
    const configuration = dependencies.configuration ?? (() => metadataLookupConfiguration());
    const musicBrainz = dependencies.musicBrainz ?? defaultMusicBrainzClient(dependencies.configuration);
    const worker = randomUUID(), claimedAt = clock();
    const claim = await lookups().findOneAndUpdate({
        state: { $in: ['queued', 'running', 'retrying'] },
        $and: [{ $or: [{ leaseUntil: null }, { leaseUntil: { $lte: claimedAt } }] }, { $or: [{ retryAt: null }, { retryAt: { $lte: claimedAt } }] }]
    }, { $set: { leaseOwner: worker, leaseUntil: new Date(claimedAt.getTime() + JOB.leaseMs) } }, { sort: { updatedAt: 1 }, returnDocument: 'after' });
    const claimed = claim.value;
    if (!claimed) return false;
    let result: LookupStepResult | null = null;
    for (let steps = 0; steps < maximumStepsPerTick; steps++) {
        const step = await advanceLookup(claimed._id, claimed.run, worker, clock(), result, configuration);
        if (!step.action) return true;
        if (signal?.aborted) break;
        result = await performLookupAction(musicBrainz, step.action, step.mode, signal);
        if (result.kind === 'shutdown') break;
    }
    // Shutdown (or the safety bound): the request in flight is discarded and the stored progress resumes on the next claim.
    await releaseLookupLease(claimed._id, claimed.run, worker);
    return true;
}

/** Process-independent persisted queue; dependencies (gate, transport, cache) are created lazily at the first due run. */
export function startMetadataLookupWorker(dependencies: MetadataLookupWorkerDependencies = {},
    intervalMs: number = JOB.workerIntervalMs, track?: AdminWorkTracker): () => Promise<void> {
    let resolved: MetadataLookupWorkerDependencies | undefined;
    return startAdminWorker(async signal => {
        // The production gate binds the connected database, so nothing is resolved before there is one.
        if (signal.aborted || !importEnabled() || (!dependencies.musicBrainz && !getDb())) return false;
        resolved ??={ ...dependencies, musicBrainz: dependencies.musicBrainz ?? defaultMusicBrainzClient(dependencies.configuration) };
        return runMetadataLookupOnce(resolved, signal);
    }, intervalMs, track);
}
